    private static readonly Dictionary<string, StudioHelpEntry> ByKey = BuildIndex();

    public static IReadOnlyList<StudioHelpEntry> Entries => All;

    public static StudioHelpEntry? Find(string? key) => key is not null && ByKey.TryGetValue(key, out var e) ? e : null;

    /// <summary>카탈로그 항목 중 도움말 누락 · 빈 필드 · 임시 문구 · 끊긴 연관 링크가 있는 키 수(0 이어야 정상).</summary>
    public static int CountDefects(List<string>? report = null)
    {
        var n = 0;
        foreach (var c in StudioCatalog.Entries)
        {
            var h = Find(c.Key);
            string? why = h is null ? "누락"
                : Blank(h.RoleSummary) || Blank(h.IntentKeywords) ? "빈 역할/키워드"
                : h.KeyControlsGuide.Length != 3 || AnyBlank(h.KeyControlsGuide) ? "핵심 조작 3 불릿 아님"
                : h.QuickWorkflow.Length != 3 || AnyBlank(h.QuickWorkflow) ? "작업 순서 3 단계 아님"
                : h.RelatedMenuIds.Length == 0 || !AllResolvable(h) ? "연관 메뉴 끊김"
                : null;
            if (why is null) continue;
            n++;
            report?.Add(c.Key + " — " + why);
        }
        return n;
    }

    /// <summary>모달 헤더 텍스트(JS 가 ? 클릭 시 전달) → 카탈로그 키. 아이콘 · 접미 "(스토리보드)" 를 무시한 제목 포함 판정 — 가장 긴 제목 우선.</summary>
    public static string? ResolveKeyByHeader(string? header)
    {
        if (string.IsNullOrWhiteSpace(header)) return null;
        var text = header.AsSpan();
        string? best = null;
        var bestLen = 0;
        foreach (var e in StudioCatalog.Entries)
        {
            var t = e.Title.AsSpan();
            var cut = t.IndexOf(" (스토리보드)".AsSpan(), StringComparison.Ordinal);
            if (cut > 0) t = t[..cut];
            if (t.Length > bestLen && text.Contains(t, StringComparison.OrdinalIgnoreCase)) { best = e.Key; bestLen = t.Length; }
        }
        return best;
    }

    public static StudioEntry? Entry(string key)
    {
        foreach (var e in StudioCatalog.Entries) if (e.Key == key) return e;
        return null;
    }

    private static bool AllResolvable(StudioHelpEntry h)
    {
        foreach (var r in h.RelatedMenuIds) if (r == h.Key || Entry(r) is null) return false;
        return true;
    }

    private static bool Blank(string s) => string.IsNullOrWhiteSpace(s) || s.Contains("작성 중", StringComparison.Ordinal) || s.Contains("TODO", StringComparison.OrdinalIgnoreCase);

    private static bool AnyBlank(string[] a)
    {
        foreach (var s in a) if (Blank(s)) return true;
        return false;
    }

    private static Dictionary<string, StudioHelpEntry> BuildIndex()
    {
        var d = new Dictionary<string, StudioHelpEntry>(All.Length, StringComparer.Ordinal);
        foreach (var e in All) d[e.Key] = e;
        return d;
    }
}
